const RIGHT = ['sky', 'far', 'sun', 'hills', 'title'];
const HAZE = .5;
farColor = mix(FAR0, FAR1, HAZE);                  // 하늘빛으로 섞기
farX = -dt * 8;  hillsX = -dt * 18;                // 가까울수록 빨리

const COPIES = 12;
for (let i = 0; i < COPIES; i++) {
  const angle = i * 2 * Math.PI / COPIES + t * .1;      // 30° 씩
  const alpha = lerp(.8, .35, i / (COPIES - 1));        // 불투명도 80% → 35%
  const grow = easeOut(seg(t, T_REP + i * .05, T_REP + i * .05 + .4));
  drawRay(sunX, sunY, angle, RAY * grow, alpha);
}
